//programs__cards
jQuery(function ($) {
  let $programsSlider = $('.programs__cards');
  function slickify() {
    $programsSlider.slick({
      slidesToShow: 4,
      slidesToScroll: 1,
      arrows: true,
      dots: false,
      autoplay: false,
      infinite: true,
      autoplaySpeed: 5000,
      speed: 500,
      cssEase: "ease-in-out",
      responsive: [
        {
          breakpoint: 1200,
          settings: {
            slidesToShow: 3,
          }
        },
		{
          breakpoint: 992,
          settings: {
            slidesToShow: 2,
          }
        },
		{
          // 2027 catalog: 10 programs, so phones get a one-card carousel instead of a long stack
          breakpoint: 768,
          settings: {
            slidesToShow: 1,
          }
        }
      ]
    });
  }

  $(window).on('load', function () {
    slickify();
  });
});